    "scene_notes": "1. 隐藏人物两名，分別是：可選关卡中，在東京出現的ガラリア；STAGE11的ロザミィ 具體加入方法下面會講 2.忍者眾請改EN到210以上，衝擊零改者請給ジョウ裝上鬥爭心 技能先不用急著裝，因为宇宙篇繼承的是地球篇最终战時的技能，什么時候剛好拿到了再裝不遲 我只是先提个醒:p ■■ 版面選擇：新宿、ムートロン研究所、伊賀の里、東京 分析 1.新宿：彈劾凰入队，5回合過版难度中等 2.ムートロン研究所：萊丁係入队，獲取熟练度要求先經過新宿之战，5回合過版不可 3.伊賀の里：5回合過版可能，BOSSイルボラ挑战难度高 4.東京：圣战士2體入队，多蒙、阿蓮比入队，萊丁在場會發生与原種共鳴的劇情（就两句话），無BOSS，5回合過版易 ■■ 綜上，新宿必須在ムートロン研究所之前選擇；伊賀の里可以放到最後，因为要積蓄足夠的兵力對付イルボラ；先去東京可以拿到强力队友 ， 包括第一次出現的精神“應援”，但是少了萊丁的劇情 因此建議如下：推薦路线是東京→新宿→ムートロン研究所→伊賀の里，这樣對战力和精神的利用是最完善的 而像我这種完美主義者，選擇 新宿→ムートロン研究所→東京→伊賀の里 这條路线，这樣就不會錯過每一个細節 （话是这么說，零改同時衝5回合跟熟练度頗有难度啊T.T）",
