    "scene_notes": "■■ 世界編的3个SELECT关卡是地球篇最麻煩的多擇，具體為 ニューヨーク： ショウ說得トッド ， 放在第3順位選擇進入4A「魂の故鄉 」 ，否則進入4B「地底帝國侵略 」 東南アジアジオン秘密基地： 第1、2順位選擇發生GP-02A搶奪事件； シロー击坠アイナ後發生雪山事件，是以後アイナ和ノリス加入的必要前提 ，但是發生此事件後シロー會離队，直到SELECT关卡全部完成後復歸 中央アジア砂漠地帶：プル出場，击坠後入队治療，但暫不出战； シロー出战的場合得到MSケンプファー（第2、3順位限定） &nbsp; ■■■■ 完全分析： 先記住这句话，这个多擇無論如何不可能做到完美 ■■ 那么，我們先來看看4A和4B这两个分支的情況 4A 是圣战士路线， 出場人物為主角（他會随著路线變動）、高达係、圣战士係、蓋塔、鳳雷鷹、黑獅子，沒有母艦（爆） ，但有圣战艦；得到的强化以移動力和运動性为主，包括灵光推進器；可以提早得到比爾拜因（啤酒:p），在第三部的銀河篇還能進一步改造为 迷彩啤酒 ；此外，還包括隐藏机体ライネック和幾名圣战士人物图鑑， 以及，可以和小羅麗幹一架:p ；关卡总體來説，過关易，拿5回合难 4B 是地上路线， 出場人物為主角、除蓋塔以外的傳統超級係、爆龙、巴尼等；强化以装甲为主 ，但是可以拿到 精神エナジー裝置 和 V-UP（W） ；得到隐藏机体量產型大魔神或者V-UP（U）（根據SCENE1鉄也甲兒的二擇決定）；克連泰沙暫時入队，获得宝貴的先期改造機會，為宇宙篇打下基礎；還有就是最重要的， 直接关係到東方不敗入队的明鏡止水劇情 ；关卡方面，無論是趕時間或者熟练度都頗有难度 從为了第二、第三部战斗考量的角度來看，無疑4B是更好的選擇，如果沒有東方不敗的话，相當于削去了多蒙1/3的战力（合体技），而V-UP（W）在初期也是很宝貴的强化；但是走4A優先拿到啤酒的话，地球篇剩下的战斗會輕鬆不少，而且迷彩啤酒的能力也頗为不俗 究竟孰优孰劣，請同學們自行決斷，在此先提一句，咲夜老师選的是4B ■■ 然後是另两个关卡的順序 從上面列出的事件來看，アイナ跟ノリス要入队就必須得發生雪山事件，而一旦雪山事件出現的话，シロー將强制離队一段時間，但为了拿ケンプファー要求シロー必須在場，那么， 滿足这两个条件的順序是中央アジア砂漠地帶→東南アジアジオン秘密基地 但是，这樣的话走4A就無法拿到ケンプファー，而且，如果我要走4B呢？ 走4B的话，在不打亂上述順序的前提下，東南アジアジオン秘密基地这一话就會被擠到最後 擠到最後的结果是什么？ 請回头看上面：東南アジアジオン秘密基地 第1、2順位選擇發生GP-02A搶奪事件 也就是說，这话最後選的话將錯過GP-02A搶奪事件（卡多已經溜走了） 錯過的壞處是什么？ 1.該话熟练度over（要求击破卡多）；2.卡多身上的强化over（ V-UP(U) ）；3.卡多會以核彈襲擊所羅門要塞，並破壞其中的隐藏机体——百式改or 全裝百式改 錯過的好處是什么？ 1.此话拿5回合希望大增（爆）；2.宇宙篇卡多襲擊所羅門一话可以拿到熟练度（在地上把他击坠的话將不出現）；3.同一话，拿到他身上的强化道具（大型彈匣） 比較一下吧，熟练度必丟其一，这个不用想了；强化零件來看，雖然大型彈匣在宇宙篇是比較緊缺的東西，但是V系列的汎用性顯然更好，長遠看的话建議選擇V系列；最後就是关係到隐藏机体，百式改可能不算什么，但如果是玩低熟练度的话拿到的全裝百式改可是MS係中数一数二的强者！ 因此，建議如下：進行低熟练度攻略的，强烈推薦在地球篇击破卡多；如果高熟練的话倒也不是什么很必要的事 對于追求高熟練的咲夜老师來説，也是選擇在地球篇就解決卡多，这樣可以為战力不足的宇宙篇省下一塊心病:p 當然有同學會說，我不讓シロー击坠アイナ，这樣雪山事件就不會發生，那么不就可以對換这两话去拿ケンプファー了么？ 沒錯，不過先請你看看这么做的收穫比較—— 雪山事件發生：アイナ&amp;ノリス&amp;两人座機（阿普薩拉斯II和老虎特裝型），以後在銀河篇可以得到GP-02A （为什么會和这个事件相关的原因非常之KUSO，請容許我賣关子:p） 不發生：ケンプファー&amp;人物图鑒（琪琪），ケンプファー擁有相當强力的两个武器，可惜都只有1發，而且机体能力不佳 請自行判斷:p ---------- 大致上可以選出合適的路线順序了吧 如果是決定走4A的，两條路线為 1.東南アジアジオン秘密基地→中央アジア砂漠地帶→ニューヨーク（ケンプファー和雪山事件二擇） 2.中央アジア砂漠地帶→東南アジアジオン秘密基地→ニューヨーク（無法入手ケンプファー） 如果決定走4B，那么有 1.ニューヨーク→東南アジアジオン秘密基地→中央アジア砂漠地帶（ケンプファー和雪山事件二擇） 2.ニューヨーク→中央アジア砂漠地帶→東南アジアジオン秘密基地（同時滿足ケンプファー和雪山事件，但無法趕上GP-02搶奪事件） 3.東南アジアジオン秘密基地→ニューヨーク→中央アジア砂漠地帶（ケンプファー和雪山事件二擇） 4.中央アジア砂漠地帶→ニューヨーク→東南アジアジオン秘密基地（無法入手ケンプファー，無法趕上GP-02搶奪事件） ■■■■綜上 想走4A的，如果要拿京寳梵，請選1；如果對京寳梵沒興趣，請選2，因为先過了中亞这関就有万丈加入，對战力是个不錯的補充 想走4B的，如果是第一遍玩不建議選擇2、4，因为錯過搶奪事件的損失比較大，1、3两條路线建議先去紐約，因为東南亞有4个BOSS要打，而且 雪山事件發生後シロー離队，對战力不利 那么，同學們都看懂了吧（沒看懂？我看像MX这種程度的SRW比較適合你XD） 拙者的路线選擇是4B，1号线 ニューヨーク→東南アジアジオン秘密基地→中央アジア砂漠地帶",
    "stage_number": "第13话",
    "title": "魂の故鄉から",
    "skill_req": "按击坠/回合条件达成",
    "enemies": "",
    "tactics": "战前準備：阿同學換乘Ez-8，裝上灵光推進器、V-UP（W），强化运動；多蒙裝上EN+100；超級係全員强化移動力 在東方不敗撤退前將其擊倒 ：葉月（ガンドール）、ロミナ（エルシャンク）、ショウ（ダンバイン）、ドモン（シャイニングガンダム）、アレンビー（ノーベルガンダム） トッド（ダンバイン(トッド)） HP 24000、ドレイク兵（ビアレス）X2、ドレイク兵（レプラカーン）X2、ドレイク兵（ドラムロ）X4、？？？（アインストグリート）X8 女神像附近 東方不敗（マスターガンダム(騎乘)） HP 36000 2回合後離脫 、ゾンビ兵（デスバーディ）X2，女神像两側海域 ゾンビ兵（デスネービー）X6"
