    "scene": "Scene 4B 地底帝国侵略",
    "scene_notes": "■■ 1.第一个关卡“獸战機队基地”中，如果此前在SCENE1讓暗黑大將軍成功竊取大魔神的設計图，而且鉄也沒有上宇宙的话，可以讓鉄也在此话 説得量產型大魔神 ；如果甲兒在这话登场，出現的將是タンデ，打倒他後得到 V-UPユニット（U） 2. 按照南原コネクション→大西洋火山島的順序選擇，夏京會作为敌增援出現 ；不過順序反過來的话就不會，因为那个時候他已經被萊丁幹掉了:p 3.在最後一话「嵐の中で輝いて」中， 如果此前發生了雪山事件，那么シロー就能夠說得アイナ ；此後用 アイナ和バーニィ 先後向ノリス進行說得即可讓他加入 如果沒有發生雪山事件，直接擊毀阿普薩拉斯II也能收到爱娜，但是这樣的话就無法使諾利斯和两架机体加入了 4.本SCENE完结後，克連泰沙、萊丁、艾爾珊克上宇宙增援朗德·貝爾，想要改造的請在20话之前完成（ 特別是克連泰沙，这對于宇宙篇前期的战斗有莫大的幫助 ）",
