    "scene_notes": "■■1.版面“京都”中，如果沒有在時限内完成破壞轉移裝置的任務，忍者眾就會被轉移到宇宙，出現在第二部SCENE的對應关卡中，由于忍者眾的战力目前來説對我軍影響不是很大，有興趣的同學可以考慮觸發这个事件，讓錠去宇宙迎接我們的王女姐姐，説不定還能看到她吃驚的表情呢:p 當然，觸發事件的代價是丟失一点熟练度 如果被送上了宇宙，忍者眾會在攻打百鬼科學要塞島一役中和彈劾凰一起作为增援登场 2.“早乙女研究所”版面如果放在1、2順位選擇，會有 テキサスマック 作为增援加入，而且蓋塔G會立刻登场；如果在第3、4順位選擇的，テキサスマック不會出場，蓋塔G推遲到決战百鬼帝國前加入，但是可以看到 蓋塔V.S.蓋塔G的CG動畫 3.“無人島”，在BOSS ベンメル存活的前提下，到第十回合，他會召喚出自己最得意的收藏—— G-3ガンダム和シャア专用ザク ，請以クリス、バーニイ分別击破，就可以在決战百鬼帝國前登陸使用这两架机体 4.为了宇宙篇的熟练度，請務必在本SCENE结束前 改滿万丈的武器 ■■建議：由于德州牛仔的實力實在是普普...地球篇輪不到他打主力，只有銀河篇有一関他在的话會輕鬆一点点（僅對零改而言），所以呢，如果已經打過一遍把他收錄到图鑒了的话，不妨選擇看CG吧:p 本人的選擇路线是：新火山空洞（拿回豹馬）→無人島（这话除了两台MS以外都很容易）→京都→早乙女研究所（感覺这樣跟後面一战比較連貫一点~.~）",
