    "scene_notes": "■■1.經過第一个STAGE後入手撫子号的追加裝備Yユニット和艾斯迪队的月面フレーム，同時撫子和万丈歸队 2.經過可選STAGE“フロンティアコロニーI”後，F91係的两名主角シーブック、セシリー入队 3.可選STAGE“ソロモン內部”中，如果先前沒發生卡多以核彈襲擊所羅門要塞的事件，那么可以在隐藏部屋中得到 百式改 ，如果熟练度滿足（第一順位選擇時熟练度26或以下，第二順位選擇時熟练度27或以下，第三順位選擇時熟练度28或以下，第四順位選擇時熟练度29或以下），那么將會得到遊戲中最强的MS之一 —— 全装甲百式改 ！ 4.“グリプスII内部”这一话放在前半或後半選擇將會影響敌人初期配置以及過版条件，不過對熟练度和强化道具並無影響 5.“メガノイド空間”前半選擇可在過版後得到 Xエステバリス改 ，後半則得到 ZII 6.如果在SCENE5以ロム說得了キナ，那么在最终STAGE，先做掉敌將ディオドラ，之後ロム就能再度說得キナ，同時获得特殊能力“がんばり屋” 7.低熟练度完成本篇，可以获得追加技能：統率、起死回生、援護攻击、援護防御 （未經確認） ■■ 本篇又有一个二擇：Xエステバリス改和ZII 單純從机体能力作比較，ZII明顯佔據上風，抛开不能移攻的缺点，15發不需气力初始攻击3000的米加炮真是非常的强，頗有當年完结篇中全装甲百式改之風采；而Xエステバリス改除了擁有重力波動炮map以外乏善可陳 不過通盤考慮，Xエステバリス改可以交給天野光，使用map+强运+幸运的組合；而ZII如果不是在零改的場合，銀河篇後期一般都是要求有强力P武器，或者能夠充分吸引敌人火力，这么看來其實也不是非拿不可 當然，我還是會選擇ZII的:p ■■ 推薦关卡選擇順序： ZII： フロンティアコロニーI（收F91）→ソロモン內部→メガノイド空間（ZII）→グリプスII内部 Xエステバリス改： フロンティアコロニーI→メガノイド空間→ソロモン內部→グリプスII内部 拙者選擇上面的路线",
