    "tactics": "：击破シャビロ，HP 32800，30%（9840）敗退 ：ブライト（ラー·カイラム）、ユリカ（ナデシコ·Yユニット）、忍（ダンクーガ），自選12機 ：シャビロ（シャビロ戦闘メカ）、？？？（ギルバウアー）X2、人工知能（ディラド战斗メカ）X6、？？？（ゼイ·ファー）X6 ：敌初期配置剩餘12體或以下 右下角 ケイム（ディラド決战メカ） HP 19350 不撤退、人工知能（ディラド战斗メカ）X5 ：V-UPユニット（U）（シャビロ戦闘メカ）、忍术指南書（ディラド決战メカ）、ブースター（ディラド战斗メカ） ■■这一係的敌人有个共同特点： 面目猙獰，實力平平:p 當然这只是對小雜兵而言，銀河篇決战メカ什么的都作为雜兵登场了那檔次就大不一樣囉"
