    "scene_notes": "■■1.第一个STAGE完成後，由于思兼出現故障，撫子队暫時離开；同時圣战艦グラン·ガラン和两名雜魚圣战士（就能力來看的確是雜魚沒錯）入队，如果先前在地球篇走的是4B，拿到 ビルバイン ，如果是4A，那么原有的ビルバイン會升級成为 迷彩ビルバイン 2.經過可選STAGE“ボストン”後，圣战艦ゴラオン入队，同時再加上圣战士一名，万丈亦在此役完结後歸队 3.經過可選STAGE“鬼面城”後，コンバトラーV歸队，此战中羅麗會出來 4. 本遊戲中最大的二擇出現： 可選STAGE“早乙女研究所”中，被控制的艾克賽玲出現， 此處的選擇決定今後入手純白騎士或者真蓋塔 選擇真蓋塔的場合， 故意讓敌軍侵入早乙女研究所範圍 ，本SCENE最终STAGE前自動入手 選擇純白騎士的場合， 不能讓敌軍侵入早乙女研究所，同時滿足熟练度条件（響介說得艾克賽玲） ，之後在SCENE3C可以入手 經過此役後蓋塔G、德州牛仔（如果有加入）歸队 -------------------- 分析一下这个二擇 ■■ 战力比較 真蓋塔 ：攻击力非常非常强！但是EN消耗過巨，裝了太陽能電池板也撐不了多久，同時對地的弱側依然存在，不過在宇宙中就大家都差不多了；由于蓋塔G後期战力很不夠，想讓三人組發揮的就要拿它；優点明顯缺点同樣明顯，持久战力不足，突襲能力天下無雙（單就零改而言），属于BOSS殺手一級 純白騎士： 比白騎士實力不知高了多少等级，原種大大們真好人~~作战半徑极其廣，武器威力大幅度提高，运動性在月球路线初登场時傲視群雄，近身依然有弱側，但攻击力的提升可以稍作彌補；有了純白以後艾艾就可以擺脫靶子的宿命，一躍成为攻击主力；基本上是需要有改造才能完全發揮的机体 如果單純是真蓋塔V.S.純白，那么毫無疑問建議選純白，不過再加上个合体技—— 主角限定LOVELOVE二人技，攻击力极其猛，为了讓響介的奇跡得到用武之地这就是首選，同時對白騎士的攻击力也是个不錯的補充 总结一下，打零改的建議選真蓋塔，这樣連著合体技在内可以得到两个威力很强的武器，對拿熟练度很有幫助；而有純白在手對于某些很搶時間的关卡好處頗多，而且看著女主角風光也是挺不錯的事情:p 不過嘛，由于真蓋塔和純白关係到3个结局CG，建議大家最好能玩3遍（爆） 总之就是真蓋塔+合体技V.S.純白，從战力上來看前者稍强，實用性差不多，如何選擇就是同學們自己的事了 如果是第一遍玩呢，建議選純白啦 咲夜老师第一遍選的純白，这次就要選真蓋塔 -------------------- 5.倒数第二个STAGE（思兼之樹）通過後，撫子歸队，而且百合香跟葵純能換乘艾斯迪巴利斯，琉璃則可以當上艦長 （万歲！终于等到了） ，採礦者大叔的祝福也能派上用場了；不過以後踫到强制出擊的关卡還是會用默認人員，請注意我的战前簡報 當然，滿足前面的二擇後，就得到 真·蓋·塔！ 6.本SCENE最终战，击破ミュージィ拿到她的机体ズワァース 大致上就是这樣啦 ■■ 我的選擇路线： 鬼面城（拿孔巴V）→ボストン（拿万丈）→早乙女研究所（蓋塔G晚拿無所謂啦） （打完SELECT STAGE才想到，如果先去看了艾克賽玲再碰羅麗，不知道臺詞會怎么變= = 懶得從头打了，請有心的同學們試著把早乙女研究所放到第一順位打）",
    "stage_number": "第72话",
    "title": "呪われしジャンヌダルク",
    "skill_req": "本队增援前（3P）击破5體敌機",
    "enemies": "アレン（レプラカーン）",
    "tactics": "請給撫子裝備莉莉絲紋章，三人娘統一裝備EN+100和射程+1，真野泉再加个SP+10（如果技能已經學了集中力或SP+15就不必裝了，总之就是至少能用2个脫力的程度） 明人、凱强化气力和EN，會長强化运動和射程 修（醬噗嚕紋章、太陽能電池、U-UNIT），出擊气力105，EN恢复（小） 托多（醬噗嚕紋章、狼之紋章、U-UNIT），出擊气力115 瑪貝露（醬噗嚕紋章、移動+1、U-UNIT、超合金Z），出擊气力105，裝了超合金就不會成为敌人的標靶 加拉莉婭（醬噗嚕紋章、EN+100、超合金ZX2），出擊气力105，超合金用法同上，保證HP比托多高就對了 其餘請選派攻击主力出場，最好是近身格鬥强勁的，破解敌人的奧拉防壁，极力强化攻击力和機動力"
