    "scene_notes": "■■1.第一个STAGE“デビルコロニー內部”，石破爱爱天驚拳和熟练度二擇，熟练度要求击破DG玲，習得石破爱爱天驚拳則是要求多蒙說得DG玲...選哪个？想必不用我多說吧:p 2.可選STAGE“フィフス·ルナ”，若此前在宇宙篇滿足了對卡多的說得，那么此處先以褲襪脫落（クワトロ）說得一次，之後击破哈曼和小白臉（グレミー），最後以浦木（コウ）說得成功 这一话很多BOSS的专用機都可以在击破後撿箱子拿到，例如哈曼的白卡、古利明的昆曼薩、馬修曼的扎古3改 3.可選STAGE“グリーンオアシス宙域”，这话开始後孔巴V的状态改造會自動追加4段，想重用它的就事先改到差4段滿的樣子，省下好多錢喔~~ 4.最後一个STAGE，讓羅姆和蕾娜先後說得加魯迪，得到特殊技能“精神統一”，不過加魯迪並不能出阵 由于現在我軍實力强悍無比，怎樣選擇也不會影響攻略难度的啦，而且也沒有對先後順序有要求的選擇肢 建議選擇路线 ：フィフス·ルナ（喜歡卡多的人先來这裡，可以多用一两话~.~ 另外白卡和昆曼薩早用早划算:p）→ストーンサークル3→グリーンオアシス宙域（後面两个對調無所謂，这樣選擇是因为覺得和接下來的STAGE劇情銜接比較緊密些） ■■ 附： 從本SCENE开始才是真正意義上的合流，光是挑自己喜歡的机体、給它裝强化就已經很令人头痛了T.T 建議是这樣，選幾架鉄定主力的机体配好强化，然後就不要動（例如我的话，主角队、多蒙师徒、卡繆和超獸機神必出），接下來的名額可以根據关卡地形以及敌人配置等自行設定，比如基地攻略战就可以讓超級係擔綱，宇宙战Nu和F91可以大發揮...等等；根據敌人配置，如果對方資金很多的那就多上幾个祝福强运，不然就用鼓舞應援...总之無論怎樣選擇也行的啦，盡量試著讓大家都有練手的機會吧:p ■■ 再附： 剛才發現一个很有趣的現象，我的Nu高达本來是給羅麗2号（璞露玆）用的，現在阿同學回來了把Nu物歸原主，那么就給羅麗开核心战機吧，结果一看，無乘坐机体時，人物回避由172變成了140，开上核心战機了又回到172 等等，这是怎么回事？ 接著看其他人，發現其他擁有增加回避技能（NT、强化人、圣战士）的人也有不同程度的下降 收集数據：卡繆（NT7 回避+15 回避+10）190→147；諾利斯（回避+15）170→145；璞露玆（强化人7 回避+15）172→140；璞露（NT7）153→135；修（圣战士7 回避+15）196→163；其他無技能强化的不變 这樣看起來就很明顯了，总回避=人物普通状态回避+特殊技能修正+技能追加 就是説 什么什么技能啦都是要坐上机体才能發揮的 ， 技能裏面NT比强化人略强（L7的時候多1），圣战士和NT打平...還有什么？肉身回避修最强= = 我是不是很無聊=_=",
    "stage_number": "第90话",
    "title": "君の中の永遠",
    "skill_req": "击破惡魔高达最终型態，HP",
    "enemies": "ウルベ（グランドマスターガンダム）",
    "tactics": "：击破惡魔高达最终型態，HP ：自選战艦1艘，ドモン（ゴッドガンダム），自選12機 ：ウルベ（グランドマスターガンダム） HP 42000、ゾンビ兵（デスマスター）X4 HP 10000、ゾンビ兵（デスバーディ）X6、ゾンビ兵（デスアーミー）X6 3E 出擊点两側 バースト（ブラスト） HP 30200 30%（9060）敗退、フラッシュ（ライドール） HP 31400 30%（9420）敗退、人工知能（ブラッディI）X4 HP 15500、人工知能（空中战車）X6 ウルベ被擊敗後 レイン（デビルガンダム(最终)） ：高性能レーダー（グランドマスターガンダム）、アルティメット細胞（デビルガンダム(最终)）、バイオセンサー（ブラスト）、アポジモーター（ライドール）"
